  1	package com.pousadamareaalta.service;
  2	
  3	import com.pousadamareaalta.model.Reservation;
  4	import com.pousadamareaalta.model.Room;
  5	
  6	import java.math.BigDecimal;
  7	import java.time.LocalDate;
  8	import java.time.YearMonth;
  9	import java.util.*;
 10	import java.util.stream.Collectors;
 11	
 12	public class ReportService {
 13	    private final ReservationService reservationService;
 14	    private static final BigDecimal TOURISM_TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
 15	
 16	    public ReportService(ReservationService reservationService) {
 17	        this.reservationService = reservationService;
 18	    }
 19	
 20	    public String generateOccupancyReport(LocalDate date) {
 21	        StringBuilder csv = new StringBuilder();
 22	
 23	        csv.append("Pousada Maré Alta,occupancy,").append(formatDateForTitle(date)).append("\n");
 24	        csv.append("room,type,reservation,check_in,check_out\n");
 25	
 26	        List<Reservation> occupied = getOccupiedReservationsForDate(date);
 27	        int occupiedRooms = 0;
 28	
 29	        for (Reservation res : occupied) {
 30	            Room room = reservationService.getRoom(res.getRoomNumber());
 31	            csv.append(room.getNumber()).append(",")
 32	                    .append(room.getType()).append(",")
 33	                    .append(res.getId()).append(",")
 34	                    .append(formatDate(res.getCheckIn())).append(",")
 35	                    .append(formatDate(res.getCheckOut())).append("\n");
 36	            occupiedRooms++;
 37	        }
 38	
 39	        csv.append("total,").append(occupiedRooms).append("/").append(reservationService.getRooms().size()).append("\n");
 40	
 41	        return csv.toString();
 42	    }
 43	
 44	    private List<Reservation> getOccupiedReservationsForDate(LocalDate date) {
 45	        return reservationService.getReservations().values().stream()
 46	                .filter(res -> res.getStatus() != Reservation.Status.CANCELLED)
 47	                .filter(res -> isNightOccupied(res, date))
 48	                .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
 49	                .collect(Collectors.toList());
 50	    }
 51	
 52	    private boolean isNightOccupied(Reservation res, LocalDate date) {
 53	        return !date.isBefore(res.getCheckIn()) && date.isBefore(res.getCheckOut());
 54	    }
 55	
 56	    public String generateRevenueReport(YearMonth month) {
 57	        StringBuilder csv = new StringBuilder();
 58	
 59	        csv.append("Pousada Maré Alta,revenue,").append(month.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
 60	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 61	
 62	        List<Reservation> monthReservations = reservationService.getReservations().values().stream()
 63	                .filter(res -> res.getCheckIn().getYear() == month.getYear() &&
 64	                              res.getCheckIn().getMonthValue() == month.getMonthValue())
 65	                .filter(res -> isPaidReservation(res))
 66	                .sorted(Comparator.comparingInt((Reservation r) -> r.getCheckIn().getDayOfMonth())
 67	                        .thenComparingLong(Reservation::getId))
 68	                .collect(Collectors.toList());
 69	
 70	        BigDecimal total = BigDecimal.ZERO;
 71	        for (Reservation res : monthReservations) {
 72	            BigDecimal amount = res.getAmountPaid().subtract(res.getRefund() != null ? res.getRefund() : BigDecimal.ZERO);
 73	            csv.append(res.getId()).append(",")
 74	                    .append(res.getRoomNumber()).append(",")
 75	                    .append(formatDate(res.getCheckIn())).append(",")
 76	                    .append(formatDate(res.getCheckOut())).append(",")
 77	                    .append(res.getStatus()).append(",")
 78	                    .append(reservationService.formatMoneyForCsv(amount)).append("\n");
 79	            total = total.add(amount);
 80	        }
 81	
 82	        csv.append("total,,,,").append(reservationService.formatMoneyForCsv(total)).append("\n");
 83	
 84	        return csv.toString();
 85	    }
 86	
 87	    public String generateTourismTaxReport(YearMonth month) {
 88	        StringBuilder csv = new StringBuilder();
 89	
 90	        csv.append("Pousada Maré Alta,tourism-tax,").append(month.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
 91	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
 92	
 93	        List<Reservation> monthReservations = reservationService.getReservations().values().stream()
 94	                .filter(res -> res.getCheckIn().getYear() == month.getYear() &&
 95	                              res.getCheckIn().getMonthValue() == month.getMonthValue())
 96	                .filter(res -> isPaidReservation(res))
 97	                .sorted(Comparator.comparingInt((Reservation r) -> r.getCheckIn().getDayOfMonth())
 98	                        .thenComparingLong(Reservation::getId))
 99	                .collect(Collectors.toList());
100	
101	        BigDecimal totalTax = BigDecimal.ZERO;
102	        for (Reservation res : monthReservations) {
103	            BigDecimal tax = TOURISM_TAX_PER_GUEST_PER_NIGHT
104	                    .multiply(new BigDecimal(res.getGuests()))
105	                    .multiply(new BigDecimal(res.getNights()));
106	            tax = tax.setScale(2, java.math.RoundingMode.HALF_EVEN);
107	            csv.append(res.getId()).append(",")
108	                    .append(res.getRoomNumber()).append(",")
109	                    .append(formatDate(res.getCheckIn())).append(",")
110	                    .append(formatDate(res.getCheckOut())).append(",")
111	                    .append(res.getGuests()).append(",")
112	                    .append(res.getNights()).append(",")
113	                    .append(reservationService.formatMoneyForCsv(tax)).append("\n");
114	            totalTax = totalTax.add(tax);
115	        }
116	
117	        csv.append("total,,,,,").append(reservationService.formatMoneyForCsv(totalTax)).append("\n");
118	
119	        return csv.toString();
120	    }
121	
122	    public String generateRatePlansReport(YearMonth month) {
123	        StringBuilder csv = new StringBuilder();
124	
125	        csv.append("Pousada Maré Alta,rate-plans,").append(month.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
126	        csv.append("rate_plan,reservations,amount\n");
127	
128	        Map<Reservation.RatePlan, Long> reservationCounts = new EnumMap<>(Reservation.RatePlan.class);
129	        Map<Reservation.RatePlan, BigDecimal> amounts = new EnumMap<>(Reservation.RatePlan.class);
130	
131	        for (Reservation.RatePlan plan : Reservation.RatePlan.values()) {
132	            reservationCounts.put(plan, 0L);
133	            amounts.put(plan, BigDecimal.ZERO);
134	        }
135	
136	        List<Reservation> monthReservations = reservationService.getReservations().values().stream()
137	                .filter(res -> res.getCheckIn().getYear() == month.getYear() &&
138	                              res.getCheckIn().getMonthValue() == month.getMonthValue())
139	                .filter(res -> isPaidReservation(res))
140	                .collect(Collectors.toList());
141	
142	        for (Reservation res : monthReservations) {
143	            reservationCounts.put(res.getRatePlan(), reservationCounts.get(res.getRatePlan()) + 1);
144	            BigDecimal amount = res.getAmountPaid().subtract(res.getRefund() != null ? res.getRefund() : BigDecimal.ZERO);
145	            amounts.put(res.getRatePlan(), amounts.get(res.getRatePlan()).add(amount));
146	        }
147	
148	        long totalReservations = 0;
149	        BigDecimal totalAmount = BigDecimal.ZERO;
150	        for (Reservation.RatePlan plan : Reservation.RatePlan.values()) {
151	            csv.append(plan).append(",")
152	                    .append(reservationCounts.get(plan)).append(",")
153	                    .append(reservationService.formatMoneyForCsv(amounts.get(plan))).append("\n");
154	            totalReservations += reservationCounts.get(plan);
155	            totalAmount = totalAmount.add(amounts.get(plan));
156	        }
157	
158	        csv.append("total,").append(totalReservations).append(",").append(reservationService.formatMoneyForCsv(totalAmount)).append("\n");
159	
160	        return csv.toString();
161	    }
162	
163	    private boolean isPaidReservation(Reservation res) {
164	        return res.getStatus() == Reservation.Status.CONFIRMED ||
165	               res.getStatus() == Reservation.Status.CHECKED_IN ||
166	               res.getStatus() == Reservation.Status.CHECKED_OUT;
167	    }
168	
169	    private String formatDate(LocalDate date) {
170	        return date.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd"));
171	    }
172	
173	    private String formatDateForTitle(LocalDate date) {
174	        return date.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd"));
175	    }
176	}

