  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import com.pousadamareaalta.model.Message;
  6	import com.pousadamareaalta.model.Reservation;
  7	import com.pousadamareaalta.service.PricingService;
  8	import com.pousadamareaalta.service.ReportService;
  9	import com.pousadamareaalta.service.ReservationService;
 10	import io.javalin.Javalin;
 11	import io.javalin.http.BadRequestResponse;
 12	import io.javalin.http.ConflictResponse;
 13	import io.javalin.http.NotFoundResponse;
 14	
 15	import java.math.BigDecimal;
 16	import java.time.LocalDate;
 17	import java.time.YearMonth;
 18	import java.time.format.DateTimeFormatter;
 19	
 20	public class Main {
 21	    private static final ObjectMapper mapper = new ObjectMapper();
 22	    private static final ReservationService reservationService = new ReservationService();
 23	    private static final ReportService reportService = new ReportService(reservationService);
 24	    private static final PricingService pricingService = new PricingService();
 25	
 26	    public static void main(String[] args) {
 27	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 28	
 29	        Javalin app = Javalin.create()
 30	                .start(port);
 31	
 32	        app.get("/rooms", ctx -> {
 33	            ctx.json(reservationService.getRooms().stream().map(room -> new java.util.HashMap<String, Object>() {{
 34	                put("number", room.getNumber());
 35	                put("type", room.getType());
 36	                put("capacity", room.getCapacity());
 37	                put("nightlyRate", formatPrice(room.getNightlyRate()));
 38	            }}).toList());
 39	        });
 40	
 41	        app.post("/reservations", ctx -> {
 42	            try {
 43	                JsonNode body = mapper.readTree(ctx.body());
 44	
 45	                if (!hasRequiredFields(body, "roomNumber", "guestName", "guestEmail", "guestCpf", "checkIn", "checkOut", "guests", "ratePlan")) {
 46	                    throw new BadRequestResponse("INVALID_REQUEST");
 47	                }
 48	
 49	                int roomNumber = body.get("roomNumber").asInt();
 50	                String guestName = body.get("guestName").asText();
 51	                String guestEmail = body.get("guestEmail").asText();
 52	                String guestCpf = body.get("guestCpf").asText();
 53	                LocalDate checkIn = LocalDate.parse(body.get("checkIn").asText(), DateTimeFormatter.ISO_LOCAL_DATE);
 54	                LocalDate checkOut = LocalDate.parse(body.get("checkOut").asText(), DateTimeFormatter.ISO_LOCAL_DATE);
 55	                int guests = body.get("guests").asInt();
 56	                Reservation.RatePlan ratePlan = Reservation.RatePlan.valueOf(body.get("ratePlan").asText());
 57	
 58	                Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail,
 59	                        guestCpf, checkIn, checkOut, guests, ratePlan);
 60	
 61	                ctx.status(201);
 62	                ctx.json(serializeReservation(reservation));
 63	            } catch (IllegalArgumentException e) {
 64	                handleReservationError(ctx, e.getMessage());
 65	            } catch (Exception e) {
 66	                ctx.status(400);
 67	                ctx.json(new java.util.HashMap<String, Object>() {{
 68	                    put("error", "INVALID_REQUEST");
 69	                    put("message", "Invalid request");
 70	                }});
 71	            }
 72	        });
 73	
 74	        app.get("/reservations/{id}", ctx -> {
 75	            try {
 76	                long id = Long.parseLong(ctx.pathParam("id"));
 77	                Reservation reservation = reservationService.getReservation(id);
 78	                if (reservation == null) {
 79	                    throw new NotFoundResponse("RESERVATION_NOT_FOUND");
 80	                }
 81	                ctx.json(serializeReservation(reservation));
 82	            } catch (NumberFormatException e) {
 83	                ctx.status(404);
 84	                ctx.json(new java.util.HashMap<String, Object>() {{
 85	                    put("error", "RESERVATION_NOT_FOUND");
 86	                    put("message", "Reservation not found");
 87	                }});
 88	            }
 89	        });
 90	
 91	        app.post("/reservations/{id}/confirmation", ctx -> {
 92	            try {
 93	                long id = Long.parseLong(ctx.pathParam("id"));
 94	                Reservation reservation = reservationService.getReservation(id);
 95	                if (reservation == null) {
 96	                    throw new BadRequestResponse("RESERVATION_NOT_FOUND");
 97	                }
 98	                reservationService.confirmReservation(id, reservation.getTotal());
 99	                ctx.json(serializeReservation(reservation));
100	            } catch (NumberFormatException e) {
101	                ctx.status(404);
102	                ctx.json(new java.util.HashMap<String, Object>() {{
103	                    put("error", "RESERVATION_NOT_FOUND");
104	                    put("message", "Reservation not found");
105	                }});
106	            } catch (IllegalArgumentException e) {
107	                handleReservationError(ctx, e.getMessage());
108	            }
109	        });
110	
111	        app.post("/reservations/{id}/cancellation", ctx -> {
112	            try {
113	                long id = Long.parseLong(ctx.pathParam("id"));
114	                Reservation reservation = reservationService.getReservation(id);
115	                if (reservation == null) {
116	                    throw new BadRequestResponse("RESERVATION_NOT_FOUND");
117	                }
118	                reservationService.cancelReservation(id);
119	                ctx.json(serializeReservation(reservation));
120	            } catch (NumberFormatException e) {
121	                ctx.status(404);
122	                ctx.json(new java.util.HashMap<String, Object>() {{
123	                    put("error", "RESERVATION_NOT_FOUND");
124	                    put("message", "Reservation not found");
125	                }});
126	            } catch (IllegalArgumentException e) {
127	                handleReservationError(ctx, e.getMessage());
128	            }
129	        });
130	
131	        app.post("/reservations/{id}/check-in", ctx -> {
132	            try {
133	                long id = Long.parseLong(ctx.pathParam("id"));
134	                Reservation reservation = reservationService.getReservation(id);
135	                if (reservation == null) {
136	                    throw new BadRequestResponse("RESERVATION_NOT_FOUND");
137	                }
138	                reservationService.checkIn(id);
139	                ctx.json(serializeReservation(reservation));
140	            } catch (NumberFormatException e) {
141	                ctx.status(404);
142	                ctx.json(new java.util.HashMap<String, Object>() {{
143	                    put("error", "RESERVATION_NOT_FOUND");
144	                    put("message", "Reservation not found");
145	                }});
146	            } catch (IllegalArgumentException e) {
147	                handleReservationError(ctx, e.getMessage());
148	            }
149	        });
150	
151	        app.post("/reservations/{id}/check-out", ctx -> {
152	            try {
153	                long id = Long.parseLong(ctx.pathParam("id"));
154	                Reservation reservation = reservationService.getReservation(id);
155	                if (reservation == null) {
156	                    throw new BadRequestResponse("RESERVATION_NOT_FOUND");
157	                }
158	                reservationService.checkOut(id);
159	                ctx.json(generateReceipt(reservation));
160	            } catch (NumberFormatException e) {
161	                ctx.status(404);
162	                ctx.json(new java.util.HashMap<String, Object>() {{
163	                    put("error", "RESERVATION_NOT_FOUND");
164	                    put("message", "Reservation not found");
165	                }});
166	            } catch (IllegalArgumentException e) {
167	                handleReservationError(ctx, e.getMessage());
168	            }
169	        });
