386	public class PricingService {
387	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
388	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
389	
390	    public boolean isHighSeason(LocalDate date) {
391	        Month month = date.getMonth();
392	        int day = date.getDayOfMonth();
393	
394	        if (month == Month.JULY) {
395	            return true;
396	        }
397	
398	        if (month == Month.DECEMBER && day >= 15) {
399	            return true;
400	        }
401	
402	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
403	            if (month == Month.FEBRUARY && day > 28) {
404	                return false;
405	            }
406	            return true;
407	        }
408	
409	        return false;
410	    }
411	
412	    public BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
413	        BigDecimal price = baseRate;
414	        if (isHighSeason(date)) {
415	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
416	        }
417	        return round(price);
418	    }
419	
420	    public BigDecimal calculateSubtotal(BigDecimal nightlyPrice, long nights) {
421	        BigDecimal subtotal = nightlyPrice.multiply(new BigDecimal(nights));
422	        return round(subtotal);
423	    }
424	
425	    public BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
426	        if (!isNonRefundable) {
427	            return BigDecimal.ZERO;
428	        }
429	        BigDecimal discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
430	        return round(discount);
431	    }
432	
433	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
434	        BigDecimal total = subtotal.subtract(discount);
435	        return round(total);
436	    }
437	
438	    public BigDecimal round(BigDecimal value) {
439	        return value.setScale(2, RoundingMode.HALF_EVEN);
440	    }
441	}
