486	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
487	                                        int guests, Reservation.RatePlan ratePlan) {
488	        Room room = rooms.get(roomNumber);
489	
490	        if (room == null) {
491	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
492	        }
493	
494	        if (guests < 1 || guests > room.getCapacity()) {
495	            throw new IllegalArgumentException(guests > room.getCapacity() ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST");
496	        }
497	
498	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
499	            throw new IllegalArgumentException("INVALID_REQUEST");
500	        }
501	
502	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
503	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
504	        }
505	
506	        long nights = calculateNights(checkIn, checkOut);
507	        BigDecimal nightlyPrice = pricingService.calculateNightlyPrice(room.getNightlyRate(), checkIn);
508	        BigDecimal subtotal = pricingService.calculateSubtotal(nightlyPrice, nights);
509	        boolean isNonRefundable = ratePlan == Reservation.RatePlan.NON_REFUNDABLE;
510	        BigDecimal discount = pricingService.calculateDiscount(subtotal, isNonRefundable);
511	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
512	
513	        Reservation reservation = new Reservation(nextReservationId++, roomNumber, guestName,
514	                guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
