  1	package com.pousadamareaalta;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import com.pousadamareaalta.model.Message;
  6	import com.pousadamareaalta.model.Reservation;
  7	import com.pousadamareaalta.service.PricingService;
  8	import com.pousadamareaalta.service.ReportService;
  9	import com.pousadamareaalta.service.ReservationService;
 10	import io.javalin.Javalin;
 11	import io.javalin.http.BadRequestResponse;
 12	import io.javalin.http.ConflictResponse;
 13	import io.javalin.http.NotFoundResponse;
 14	
 15	import java.math.BigDecimal;
 16	import java.time.LocalDate;
 17	import java.time.YearMonth;
 18	import java.time.format.DateTimeFormatter;
 19	
 20	public class Main {
 21	    private static final ObjectMapper mapper = new ObjectMapper();
 22	    private static final ReservationService reservationService = new ReservationService();
 23	    private static final ReportService reportService = new ReportService(reservationService);
 24	    private static final PricingService pricingService = new PricingService();
 25	
 26	    public static void main(String[] args) {
 27	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 28	
 29	        Javalin app = Javalin.create()
 30	                .start(port);
 31	
 32	        app.get("/rooms", ctx -> {
 33	            ctx.json(reservationService.getRooms().stream().map(room -> new java.util.HashMap<String, Object>() {{
 34	                put("number", room.getNumber());
 35	                put("type", room.getType());
 36	                put("capacity", room.getCapacity());
 37	                put("nightlyRate", formatPrice(room.getNightlyRate()));
 38	            }}).toList());
 39	        });
 40	
 41	        app.post("/reservations", ctx -> {
 42	            try {
 43	                JsonNode body = mapper.readTree(ctx.body());
 44	
 45	                if (!hasRequiredFields(body, "roomNumber", "guestName", "guestEmail", "guestCpf", "checkIn", "checkOut", "guests", "ratePlan")) {
 46	                    throw new BadRequestResponse("INVALID_REQUEST");
 47	                }
 48	
 49	                int roomNumber = body.get("roomNumber").asInt();
 50	                String guestName = body.get("guestName").asText();
 51	                String guestEmail = body.get("guestEmail").asText();
 52	                String guestCpf = body.get("guestCpf").asText();
 53	                LocalDate checkIn = LocalDate.parse(body.get("checkIn").asText(), DateTimeFormatter.ISO_LOCAL_DATE);
 54	                LocalDate checkOut = LocalDate.parse(body.get("checkOut").asText(), DateTimeFormatter.ISO_LOCAL_DATE);
 55	                int guests = body.get("guests").asInt();
 56	                Reservation.RatePlan ratePlan = Reservation.RatePlan.valueOf(body.get("ratePlan").asText());
 57	
 58	                Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail,
 59	                        guestCpf, checkIn, checkOut, guests, ratePlan);
 60	
 61	                ctx.status(201);
