  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	import java.util.*;
 10	
 11	public class ReservationService {
 12	    private final Map<Integer, Room> rooms = new HashMap<>();
 13	    private final Map<Long, Reservation> reservations = new HashMap<>();
 14	    private final List<Message> messages = new ArrayList<>();
 15	    private long nextReservationId = 1;
 16	    private long nextMessageId = 1;
 17	    private final PricingService pricingService;
 18	
 19	    public ReservationService() {
 20	        this.pricingService = new PricingService();
 21	        initializeRooms();
 22	    }
 23	
 24	    private void initializeRooms() {
 25	        rooms.put(101, new Room(101, "STANDARD", 2, new BigDecimal("249.90")));
 26	        rooms.put(102, new Room(102, "STANDARD", 2, new BigDecimal("249.90")));
 27	        rooms.put(201, new Room(201, "DELUXE", 3, new BigDecimal("389.90")));
 28	        rooms.put(202, new Room(202, "DELUXE", 3, new BigDecimal("389.90")));
 29	        rooms.put(301, new Room(301, "SUITE", 4, new BigDecimal("579.90")));
 30	    }
 31	
 32	    public Collection<Room> getRooms() {
 33	        return rooms.values();
 34	    }
 35	
 36	    public Room getRoom(int number) {
 37	        return rooms.get(number);
 38	    }
 39	
 40	    public long calculateNights(LocalDate checkIn, LocalDate checkOut) {
 41	        return java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 42	    }
 43	
 44	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
 45	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
 46	                                        int guests, Reservation.RatePlan ratePlan) {
 47	        Room room = rooms.get(roomNumber);
 48	
 49	        if (room == null) {
 50	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
 51	        }
 52	
 53	        if (guests < 1 || guests > room.getCapacity()) {
 54	            throw new IllegalArgumentException(guests > room.getCapacity() ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST");
 55	        }
 56	
 57	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
 58	            throw new IllegalArgumentException("INVALID_REQUEST");
 59	        }
 60	
 61	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
 62	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
 63	        }
 64	
 65	        long nights = calculateNights(checkIn, checkOut);
 66	        BigDecimal nightlyPrice = pricingService.calculateNightlyPrice(room.getNightlyRate(), checkIn);
 67	        BigDecimal subtotal = pricingService.calculateSubtotal(nightlyPrice, nights);
 68	        boolean isNonRefundable = ratePlan == Reservation.RatePlan.NON_REFUNDABLE;
 69	        BigDecimal discount = pricingService.calculateDiscount(subtotal, isNonRefundable);
 70	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
 71	
 72	        Reservation reservation = new Reservation(nextReservationId++, roomNumber, guestName,
 73	                guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
 74	
 75	        reservations.put(reservation.getId(), reservation);
 76	        return reservation;
 77	    }
 78	
 79	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
 80	        for (Reservation res : reservations.values()) {
 81	            if (res.getRoomNumber() == roomNumber && res.getStatus() != Reservation.Status.CANCELLED) {
 82	                if (overlapsWithReservation(checkIn, checkOut, res.getCheckIn(), res.getCheckOut())) {
 83	                    return true;
 84	                }
 85	            }
 86	        }
 87	        return false;
 88	    }
 89	
 90	    private boolean overlapsWithReservation(LocalDate checkIn, LocalDate checkOut,
 91	                                           LocalDate resCheckIn, LocalDate resCheckOut) {
 92	        return !checkIn.isAfter(resCheckOut.minusDays(1)) && !checkOut.isBefore(resCheckIn.plusDays(1));
 93	    }
 94	
 95	    public Reservation getReservation(long id) {
 96	        return reservations.get(id);
 97	    }
 98	
 99	    public Map<Long, Reservation> getReservations() {
100	        return reservations;
101	    }
102	
103	    public void confirmReservation(long id, BigDecimal amountPaid) {
104	        Reservation res = reservations.get(id);
105	        if (res == null) {
106	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
107	        }
108	        if (res.getStatus() != Reservation.Status.PENDING) {
109	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
110	        }
111	        res.setStatus(Reservation.Status.CONFIRMED);
112	        res.setAmountPaid(amountPaid);
113	
114	        String receipt = generateReceipt(res);
115	        String emailBody = generateConfirmationEmail(res, receipt);
116	        sendMessage(Message.Channel.EMAIL, res.getGuestEmail(),
117	                "Reserva confirmada - Pousada Maré Alta", emailBody);
118	    }
119	
120	    public void checkIn(long id) {
121	        Reservation res = reservations.get(id);
122	        if (res == null) {
123	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
124	        }
125	        if (res.getStatus() != Reservation.Status.CONFIRMED) {
126	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
127	        }
128	        res.setStatus(Reservation.Status.CHECKED_IN);
129	    }
130	
131	    public void checkOut(long id) {
132	        Reservation res = reservations.get(id);
133	        if (res == null) {
134	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
135	        }
136	        if (res.getStatus() != Reservation.Status.CHECKED_IN) {
137	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
138	        }
139	        res.setStatus(Reservation.Status.CHECKED_OUT);
140	    }
141	
142	    public void cancelReservation(long id) {
143	        Reservation res = reservations.get(id);
144	        if (res == null) {
145	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
146	        }
147	        if (res.getStatus() != Reservation.Status.PENDING && res.getStatus() != Reservation.Status.CONFIRMED) {
148	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
149	        }
150	
151	        BigDecimal refund = BigDecimal.ZERO;
152	        if (res.getStatus() == Reservation.Status.CONFIRMED) {
153	            if (res.getRatePlan() == Reservation.RatePlan.STANDARD) {
154	                refund = res.getAmountPaid();
155	            }
156	        }
157	
158	        res.setStatus(Reservation.Status.CANCELLED);
159	        if (refund.compareTo(BigDecimal.ZERO) > 0) {
160	            res.setRefund(refund);
161	        }
162	    }
163	
164	    public String generateReceipt(Reservation res) {
165	        StringBuilder sb = new StringBuilder();
166	        sb.append("Comprovante de reserva nº ").append(res.getId()).append("\n");
167	        sb.append("Hóspede: ").append(res.getGuestName()).append(" (CPF ").append(res.getGuestCpf()).append(")\n");
168	        sb.append("Quarto: ").append(res.getRoomNumber()).append(" (").append(getRoom(res.getRoomNumber()).getType()).append(")\n");
169	        sb.append("Entrada: ").append(formatDate(res.getCheckIn()));
170	        sb.append(" | Saída: ").append(formatDate(res.getCheckOut()));
171	        sb.append(" | ").append(res.getNights()).append(res.getNights() == 1 ? " diária\n" : " diárias\n");
172	        sb.append("Diárias: ").append(formatMoney(res.getSubtotal())).append("\n");
173	        if (res.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
174	            sb.append("Desconto: ").append(formatMoney(res.getDiscount())).append("\n");
175	        }
176	        sb.append("Total: ").append(formatMoney(res.getTotal()));
177	        return sb.toString();
178	    }
179	
180	    private String generateConfirmationEmail(Reservation res, String receipt) {
181	        StringBuilder sb = new StringBuilder();
182	        sb.append("Olá, ").append(res.getGuestName()).append("!\n\n");
183	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
184	        sb.append(receipt).append("\n\n");
185	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
186	        sb.append("Até breve!");
187	        return sb.toString();
188	    }
189	
190	    public void sendMessage(Message.Channel channel, String to, String subject, String body) {
191	        Message msg = new Message(nextMessageId++, channel, to, subject, body);
192	        messages.add(msg);
193	    }
194	
195	    public List<Message> getMessages() {
196	        return new ArrayList<>(messages);
197	    }
198	
199	    public String formatDate(LocalDate date) {
200	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
201	    }
202	
203	    public String formatMoney(BigDecimal value) {
204	        return String.format("R$ %,.2f", value).replace(",", ".");
205	    }
206	
207	    public String formatMoneyForCsv(BigDecimal value) {
208	        return String.format("%.2f", value);
209	    }
210	}
211	package com.pousadamareaalta.service;
212	
213	import java.math.BigDecimal;
214	import java.math.RoundingMode;
215	import java.time.LocalDate;
216	import java.time.Month;
217	
218	public class PricingService {
219	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
220	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
221	
222	    public boolean isHighSeason(LocalDate date) {
223	        Month month = date.getMonth();
224	        int day = date.getDayOfMonth();
225	
226	        if (month == Month.JULY) {
227	            return true;
228	        }
229	
230	        if (month == Month.DECEMBER && day >= 15) {
231	            return true;
232	        }
233	
234	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
235	            if (month == Month.FEBRUARY && day > 28) {
236	                return false;
237	            }
238	            return true;
239	        }
240	
241	        return false;
242	    }
243	
244	    public BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
245	        BigDecimal price = baseRate;
246	        if (isHighSeason(date)) {
247	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
248	        }
249	        return round(price);
250	    }
251	
252	    public BigDecimal calculateSubtotal(BigDecimal nightlyPrice, long nights) {
253	        BigDecimal subtotal = nightlyPrice.multiply(new BigDecimal(nights));
254	        return round(subtotal);
255	    }
256	
257	    public BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
258	        if (!isNonRefundable) {
259	            return BigDecimal.ZERO;
260	        }
261	        BigDecimal discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
262	        return round(discount);
263	    }
264	
265	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
266	        BigDecimal total = subtotal.subtract(discount);
267	        return round(total);
268	    }
269	
270	    public BigDecimal round(BigDecimal value) {
271	        return value.setScale(2, RoundingMode.HALF_EVEN);
272	    }
273	}

